1	package meter
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// 本文件回归“两条标识不同的事件并发上报到同一账户、同一账期，合计用量越过
12	// int64 可保存上限”的行为。
13	//
14	// 这里的上限是 int64 最大值 maxInt64（9223372036854775807），与套餐包含额度
15	// 无关：超出套餐额度的用量仍按原规则记录。实现把“去重判定 → 时刻/账期/停用
16	// 校验 → 溢出检查 → 事件与累计落库”全部放在同一把互斥锁的一个临界区内，因此
17	// 两笔请求必然串行裁决：先到的一笔按当时累计落库，后到的一笔看到的是包含先到
18	// 一笔的真实累计，合计放不下时整次请求失败并返回 ErrOverflow，且失败发生在
19	// 落库之前，不占用事件标识、不增加累计用量。
20	//
21	// 这些测试锁住该行为，防止日后把“读取累计 → 溢出判断 → 写回”拆成多个步骤
22	// （TOCTOU）而出现：两笔都成功、累计越过 maxInt64、先前用量丢失、负数、失败
23	// 笔占用标识，或已接收事件的原样重报在累计到顶后被误判为溢出。可观察结果同时
24	// 覆盖上报返回、MonthlyUsage 与 Status 中的单月用量。
25	
26	// eventOutcome 记录一笔并发上报的标识、时刻、数量与返回结果。
27	type eventOutcome struct {
28		id  string
29		at  time.Time
30		qty int64
31		r   EventResult
32		err error
33	}
34	
35	// setupNearCapAccount 在指定账户上把 2026-01 的累计用量垫到距 int64 上限只剩
36	// 10 个单位：账户已有实际生效的订阅、无账单（账期尚未出账）、无欠费，种子事件
37	// 此前从未接收过。返回种子累计值 maxInt64-10。
38	func setupNearCapAccount(t *testing.T, s *Service, acct string) int64 {
39		t.Helper()
40		mustAccount(t, s, acct)
41		if err := s.Subscribe(acct, "p", utc(2026, 1, 1, 0, 0)); err != nil {
42			t.Fatalf("subscribe %q: %v", acct, err)
43		}
44		base := maxInt64 - 10
45		r, err := s.RecordEvent(Event{
46			AccountID: acct,
47			EventID:   "base-" + acct,
48			At:        utc(2026, 1, 10, 0, 0),
49			Quantity:  base,
50		})
51		if err != nil || !r.Accepted || r.Period != jan(2026) {
52			t.Fatalf("seed base usage %q: r=%+v err=%v", acct, r, err)
53		}
54		return base
55	}
56	
57	// contendEventsOnce 用启动屏障让两条不同标识的事件在同一时刻争用同一账期的
58	// 累计值，返回与传入顺序一致的两笔结果。屏障保证两笔真正并发，而非顺序提交。
59	func contendEventsOnce(s *Service, acct string, first, second eventOutcome) []eventOutcome {
60		reqs := []eventOutcome{first, second}
61		res := make([]eventOutcome, 2)
62		start := make(chan struct{})
63		var wg sync.WaitGroup
64		wg.Add(2)
65		for i, q := range reqs {
66			go func(i int, q eventOutcome) {
67				defer wg.Done()
68				<-start
69				r, err := s.RecordEvent(Event{
70					AccountID: acct,
71					EventID:   q.id,
72					At:        q.at,
73					Quantity:  q.qty,
74				})
75				res[i] = eventOutcome{id: q.id, at: q.at, qty: q.qty, r: r, err: err}
76			}(i, q)
77		}
78		close(start)
79		wg.Wait()
80		return res
81	}
82	
83	// statusMonthUsage 返回账户状态中指定账期的用量条目，要求该账期必须出现。
84	func statusMonthUsage(t *testing.T, s *Service, acct string, m Month) Usage {
85		t.Helper()
86		st, err := s.Status(acct)
87		if err != nil {
88			t.Fatalf("status %q: %v", acct, err)
89		}
90		for _, u := range st.MonthlyUsage {
91			if u.Period == m {
92				return u
93			}
94		}
95		t.Fatalf("status %q has no usage for %s: %+v", acct, m, st.MonthlyUsage)
96		return Usage{}
97	}
98	
99	// assertUsageAtCap 断言单月用量查询与账户状态中的该月用量都恰好等于 int64 上限，
100	// 且账户仍为已订阅、未停用。
101	func assertUsageAtCap(t *testing.T, s *Service, acct string) {
102		t.Helper()
103		u, err := s.MonthlyUsage(acct, jan(2026))
104		if err != nil {
105			t.Fatalf("monthly usage %q: %v", acct, err)
106		}
107		if u.Total != maxInt64 {
108			t.Fatalf("%q monthly usage = %d, want %d", acct, u.Total, maxInt64)
109		}
110		if got := statusMonthUsage(t, s, acct, jan(2026)); got.Total != maxInt64 {
111			t.Fatalf("%q status monthly usage = %d, want %d", acct, got.Total, maxInt64)
112		}
113		st, err := s.Status(acct)
114		if err != nil {
115			t.Fatalf("status %q: %v", acct, err)
116		}
117		if !st.Subscribed || st.Suspended {
118			t.Fatalf("%q status: subscribed=%v suspended=%v, want true/false", acct, st.Subscribed, st.Suspended)
119		}
120	}
121	
122	// TestConcurrentDistinctEventsOnlyOneWithinInt64Cap 覆盖主例子：
123	// 账期累计距 int64 上限只剩 10 单位时，7 单位与 8 单位两条不同标识的事件并发
124	// 到达。两笔单独看都能放下，合计（15）放不下：恰好一笔首次接收，另一笔整次
125	// 请求失败并可被 errors.Is 识别为 ErrOverflow。允许任意一笔先成功。
126	func TestConcurrentDistinctEventsOnlyOneWithinInt64Cap(t *testing.T) {
127		s, _ := newTestService(utc(2026, 1, 20, 12, 0))
128		// 套餐包含额度与本次断言无关：越过套餐额度的用量照常记录，只受 int64 上限约束。
129		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
130	
131		const rounds = 100
132		for iter := 0; iter < rounds; iter++ {
133			acct := fmt.Sprintf("a%d", iter)
134			base := setupNearCapAccount(t, s, acct)
135			at7 := utc(2026, 1, 11, 0, 0)
136			at8 := utc(2026, 1, 11, 0, 1)
137	
138			res := contendEventsOnce(s, acct,
139				eventOutcome{id: "e7", at: at7, qty: 7},
140				eventOutcome{id: "e8", at: at8, qty: 8},
141			)
142	
143			// 恰好一笔首次接收成功、恰好一笔溢出失败；不允许两笔都成功，
144			// 也不允许返回冲突等其它错误。
145			var winner eventOutcome
146			var loser *eventOutcome
147			nAccepted, nOverflow := 0, 0
148			for i := range res {
149				oc := &res[i]
150				switch {
151				case oc.err == nil && oc.r.Accepted:
152					nAccepted++
153					winner = *oc
154					if oc.r.Period != jan(2026) {
155						t.Fatalf("iter %d accepted %q in wrong period: %+v", iter, oc.id, oc.r)
156					}
157				case errors.Is(oc.err, ErrOverflow):
158					nOverflow++
159					loser = oc
160				default:
161					t.Fatalf("iter %d event %q unexpected: r=%+v err=%v", iter, oc.id, oc.r, oc.err)
162				}
163			}
164			if nAccepted != 1 || nOverflow != 1 || loser == nil {
165				t.Fatalf("iter %d want exactly one accepted and one overflow, got %+v", iter, res)
166			}
167	
168			// 成功接收的事件数量必须与最终累计值一致：原累计 + 成功一笔的数量。
169			wantTotal := base + winner.qty
170			if wantTotal < 0 || wantTotal > maxInt64 {
171				t.Fatalf("iter %d winner %q drives total out of range: %d", iter, winner.id, wantTotal)
172			}
173			u, err := s.MonthlyUsage(acct, jan(2026))
174			if err != nil {
175				t.Fatalf("iter %d monthly usage: %v", iter, err)
176			}
177			if u.Total != wantTotal {
178				t.Fatalf("iter %d monthly usage = %d, want %d", iter, u.Total, wantTotal)
179			}
180			if got := statusMonthUsage(t, s, acct, jan(2026)); got.Total != wantTotal {
181				t.Fatalf("iter %d status monthly usage = %d, want %d", iter, got.Total, wantTotal)
182			}
183	
184			// 溢出被拒的事件不占用标识：保留原标识与发生时刻，把数量改成当时尚可
185			// 累计的剩余量再提交，应作为首次上报成功，使累计恰好达到上限——
186			// 而不是被当成标识冲突或重复。
187			remaining := maxInt64 - wantTotal
188			topUp, err := s.RecordEvent(Event{
189				AccountID: acct,
190				EventID:   loser.id,
191				At:        loser.at,
192				Quantity:  remaining,
193			})
194			if errors.Is(err, ErrEventConflict) {
195				t.Fatalf("iter %d overflowed event id %q was consumed: %v", iter, loser.id, err)
196			}
197			if err != nil || !topUp.Accepted || topUp.Period != jan(2026) {
198				t.Fatalf("iter %d reuse rejected id %q for remaining %d: r=%+v err=%v",
199					iter, loser.id, remaining, topUp, err)
200			}
201			assertUsageAtCap(t, s, acct)
202	
203			// 已成功接收的事件按原内容重报：未再次接收、保留原账期；即使此时累计
204			// 已到上限，也不能报溢出或再次增加用量。
205			replay, err := s.RecordEvent(Event{
206				AccountID: acct,
207				EventID:   winner.id,
208				At:        winner.at,
209				Quantity:  winner.qty,
210			})
211			if err != nil || replay.Accepted || replay.Period != jan(2026) {
212				t.Fatalf("iter %d replay winner %q: r=%+v err=%v, want not accepted in Jan",
213					iter, winner.id, replay, err)
214			}
215			assertUsageAtCap(t, s, acct)
216		}
217	}
218	
219	// TestConcurrentDistinctEventsExactlyReachInt64Cap 覆盖刚好能容纳的边界：
220	// 从距上限 10 单位的独立初始状态，并发提交 4 单位与 6 单位的不同标识事件，
221	// 两笔均应首次接收，最终累计恰好达到上限，不能把合法的边界合计误判为溢出。
222	func TestConcurrentDistinctEventsExactlyReachInt64Cap(t *testing.T) {
223		s, _ := newTestService(utc(2026, 1, 20, 12, 0))
224		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
225	
226		const rounds = 100
227		for iter := 0; iter < rounds; iter++ {
228			acct := fmt.Sprintf("b%d", iter)
229			base := setupNearCapAccount(t, s, acct)
230	
231			res := contendEventsOnce(s, acct,
232				eventOutcome{id: "e4", at: utc(2026, 1, 11, 0, 0), qty: 4},
233				eventOutcome{id: "e6", at: utc(2026, 1, 11, 0, 1), qty: 6},
234			)
235			for _, oc := range res {
236				if oc.err != nil || !oc.r.Accepted || oc.r.Period != jan(2026) {
237					t.Fatalf("iter %d event %q should be accepted in Jan: r=%+v err=%v",
238						iter, oc.id, oc.r, oc.err)
239				}
240			}
241			// 两笔合计恰为剩余 10 单位：累计恰好到顶。
242			if want := base + 10; want != maxInt64 {
243				t.Fatalf("iter %d expected total to reach cap, got %d", iter, want)
244			}
245			assertUsageAtCap(t, s, acct)
246	
247			// 到顶后两笔各自原样重报：仍按重复处理，不再次累计、也不报溢出。
248			for _, oc := range res {
249				replay, err := s.RecordEvent(Event{
250					AccountID: acct,
251					EventID:   oc.id,
252					At:        oc.at,
253					Quantity:  oc.qty,
254				})
255				if err != nil || replay.Accepted || replay.Period != jan(2026) {
256					t.Fatalf("iter %d replay %q at cap: r=%+v err=%v, want not accepted in Jan",
257						iter, oc.id, replay, err)
258				}
259			}
260			assertUsageAtCap(t, s, acct)
261		}
262	}
263	
264	// TestDistinctEventOverflowBothOrdersDeterministic 以确定顺序锁住两种可能的
265	// 获胜结果（并发测试不保证每次都调度出两种先后顺序，这里把两条路径各自完整
266	// 走一遍）：失败笔不占标识，可保留原标识与时刻、改用当时剩余量首次接收并把
267	// 累计顶到上限；随后重报先成功的事件只返回未接收，不再次累计、不报溢出。
268	func TestDistinctEventOverflowBothOrdersDeterministic(t *testing.T) {
269		s, _ := newTestService(utc(2026, 1, 20, 12, 0))
270		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
271		at7 := utc(2026, 1, 11, 0, 0)
272		at8 := utc(2026, 1, 11, 0, 1)
273	
